#!/usr/bin/env python3
"""Regenerate doench2016_scores.tsv, the golden-score fixture.

The fixture pins score_guides output for a fixed set of guides, flanks,
and PAMs as produced by the implementation at the commit recorded in the
fixture header. Regenerate only when a scoring change is intentional,
then review the diff.

Usage:
    python tests/fixtures/regenerate_doench2016_scores.py
"""

import subprocess
import sys
from pathlib import Path

FIXTURE_DIR = Path(__file__).resolve().parent
REPO_ROOT = FIXTURE_DIR.parent.parent
OUT_PATH = FIXTURE_DIR / "doench2016_scores.tsv"

CASES = [
    # variant, guide, flank5, flank3, pam
    ("default", "GACAGCATCGTACGTTGCAG", "", "", ""),
    ("default", "ATATATATATATATATATAT", "", "", ""),
    ("default", "GCGCGCGCGCGCGCGCGCGC", "", "", ""),
    ("default", "TTTTTTTTTTTTTTTTTTTT", "", "", ""),
    ("default", "AGCTAGCTAGCTAGCTAGCT", "", "", ""),
    ("pams", "GACAGCATCGTACGTTGCAG", "", "", "AGA"),
    ("pams", "CAATGCTAGCTAGGCATCAT", "", "", "CCA"),
    ("pams", "ATGCCCGTTAGGCTAACCTG", "", "", "TTT"),
    ("full", "GACAGCATCGTACGTTGCAG", "ACGTACGTAC", "TTGGCCAATT", "AGA"),
    ("full", "CAATGCTAGCTAGGCATCAT", "TTTTGGGAA", "CCAT", "NGG"),
    ("full", "TCCAGCTATGACGATTACCA", "GGCATGCATG", "AGTCGTAGCT", "CCA"),
    ("full", "ATGCCCGTTAGGCTAACCTG", "AAAAACCCCC", "GGGGTTTT", "TTT"),
    ("full", "GGAAAATGGGCCTTAGAGCT", "CTAGCTAGCT", "AATTCCGG", "NGG"),
]


def build_score_rows(cases):
    """Score every case with the call variant its row describes."""
    import crispytargets.design.doench2016 as doench2016

    rows = []
    for variant, guide, flank5, flank3, pam in cases:
        if variant == "default":
            score = float(doench2016.score_guides([guide])[0])
        elif variant == "pams":
            score = float(doench2016.score_guides([guide], pams=[pam])[0])
        elif variant == "full":
            score = float(
                doench2016.score_guides([guide], flanks=[(flank5, flank3)], pams=[pam])[0]
            )
        else:
            raise ValueError(f"unknown variant: {variant}")
        rows.append((variant, guide, flank5, flank3, pam, score))
    return rows


def write_fixture(rows):
    import Bio
    import numpy

    commit = subprocess.run(
        ["git", "rev-parse", "--short", "HEAD"], capture_output=True, text=True, cwd=REPO_ROOT
    ).stdout.strip()

    header = (
        "# Golden scores from score_guides, generated by this script.\n"
        f"# git commit: {commit}\n"
        f"# biopython: {Bio.__version__} (Tm_NN feeds 4 feature slots)\n"
        f"# numpy: {numpy.__version__}\n"
        "# variant: default = no flanks, no PAM; pams = PAM only; full = flanks + PAM\n"
    )
    with open(OUT_PATH, "w") as f:
        f.write(header)
        f.write("variant\tguide\tflank5\tflank3\tpam\tscore\n")
        for variant, guide, flank5, flank3, pam, score in rows:
            f.write(f"{variant}\t{guide}\t{flank5}\t{flank3}\t{pam}\t{score:.17g}\n")
    print(f"wrote {len(rows)} rows to {OUT_PATH}")


if __name__ == "__main__":
    sys.path.insert(0, str(REPO_ROOT / "src"))
    write_fixture(build_score_rows(CASES))
